export const KMAP=Object.fromEntries([...Object.values(KQ).flat(),...QS,...ORG].map(q=>[q.id,q]));
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const ids=qs=>qs.map(q=>q.id);
// Families whose people work with concrete every day also get the technical common questions
const TECH_FAM=new Set(["quality","plant","driver","maint"]);
const TECH_COMMON=["k6","k7","k8","k11","k14"];
const COMPANY=["k1","k2","k3","k4"]; // company facts: current staff get N_ORG drawn from these plus ORG
const SAFETY=["k5","k9","k10","k12","k13","of4",...KQ.general.map(q=>q.id)];
export function commonPool(mode,fam){
  return [...SAFETY,...(TECH_FAM.has(fam)?TECH_COMMON:[])];
}
// Job questions for a position; quality roles mix in level-2 items by seniority
export function jobPool(dept,pos){
  const [,fam,l2]=posInfo(dept,pos);
  return fam==="quality"?{fam,pool:QS,l2:l2||0}:{fam,pool:KQ[fam]||KQ.general,l2:0};
}
function drawJob(dept,pos,n){
  const {pool,l2}=jobPool(dept,pos);
  if(pool!==QS)return shuffle(ids(pool)).slice(0,n);
  const two=shuffle(ids(QS.filter(q=>q.l===2))).slice(0,l2);
  return [...two,...shuffle(ids(QS.filter(q=>q.l===1))).slice(0,n-two.length)];
}
export function draw(mode,dept,pos){
  const fam=posInfo(dept,pos)[1];
  const org=mode==="apply"?[]:shuffle([...COMPANY,...ids(ORG)]).slice(0,N_ORG);
  const common=[...org,...shuffle(commonPool(mode,fam)).slice(0,mode==="apply"?APP_N_COMMON:N_COMMON)];
  const job=drawJob(dept,pos,mode==="apply"?APP_N_JOB:N_JOB).filter(id=>!common.includes(id));
  const order=[...common,...shuffle(job)];
  return {common,order,qs:Object.fromEntries(order.map(id=>[id,{q:KMAP[id].q,o:KMAP[id].o}]))};
}
